      'contact.intro': 'Questions sur une commande, écrivez à <a href="mailto:support@letterhome.ca">support@letterhome.ca</a> ou utilisez le formulaire. Envois en volume ou affaires, <a href="mailto:sales@letterhome.ca">sales@letterhome.ca</a>. Réponse dans un jour ouvrable.',
      'contact.meta1.h3': 'Soutien',
      'contact.meta1.p': '<a href="mailto:support@letterhome.ca">support@letterhome.ca</a><br>Commandes, statut de commande et questions générales.',
